"""H2: prize key generated by VanitySearch with a planted seed (-s), the tool's exact deterministic schedule:
startKey = int_le(sha256(pbkdf2_hmac_sha512(seed, 'VanitySearch', 2048, 64)))   [Vanity.cpp, verified 2026-10-14]
CPU thread t: key = startKey + t<<64 + j ;  GPU thread i: key = startKey + i<<80 + (0x80+gpu)<<112 + j
found key = +-lambda^e * key (mod n), e in {0,1,2}.  BSGS on x-coordinates vs the prize pubkey (perfect oracle).
Also 'brainwallet base + incremental vanity search' (startKey = sha256(seed) big-endian, CPU schedule).
Usage: python3 vanitysearch_seed_bsgs.py [gpu]"""
import sys, hashlib
sys.path.insert(0, '/home/vin/bitcoin_puzzle/scratch/c43/ideas_secret_sharing')
import ec
N = ec.N
BABY = 1 << 18
tab = {}; pt = None
for j in range(1, BABY + 1):
    pt = ec.add(pt, ec.G); tab[pt[0]] = j
STRIDE = 1 << 19; STRIDE_G = ec.mul(STRIDE); NSTRIDE_G = ec.neg(STRIDE_G)
def window_search(Q, ncs):
    """j with Q = j*G, 0 <= j < ncs*STRIDE + BABY (x-only, sign resolved later)"""
    R = Q
    for c in range(ncs):
        if R is None: return [c * STRIDE]
        if R[0] in tab: return [c * STRIDE + tab[R[0]], c * STRIDE - tab[R[0]]]
        R = ec.add(R, NSTRIDE_G)
    return []
def search(S, target, mode, tmax, ncs, gpus=(0,)):
    hits = []
    for e in range(3):
        for s in (1, -1):
            T = ec.mul(s * pow(ec.LAM, -e, N) % N, target)       # = (S + off + j) G
            Q0 = ec.add(T, ec.neg(ec.mul(S)))
            for g in gpus:
                Qg = Q0 if mode == 'cpu' else ec.add(Q0, ec.neg(ec.mul((0x80 + g) << 112)))
                step = ec.neg(ec.mul(1 << (64 if mode == 'cpu' else 80)))
                Q = Qg
                for t in range(tmax):
                    for j in window_search(Q, ncs):
                        off = (t << 64) if mode == 'cpu' else ((t << 80) + ((0x80 + g) << 112))
                        k = s * pow(ec.LAM, e, N) * (S + off + j) % N
                        if ec.mul(k) == target: hits.append((e, s, g, t, j, hex(k)))
                    Q = ec.add(Q, step)
    return hits
def vs_start(seed): return int.from_bytes(hashlib.sha256(hashlib.pbkdf2_hmac('sha512', seed.encode(), b'VanitySearch', 2048, 64)).digest(), 'little')
def bw_start(seed): return int.from_bytes(hashlib.sha256(seed.encode()).digest(), 'big')
# planted controls
Sc = vs_start('controlseed')
kc = (-pow(ec.LAM, 2, N) * (Sc + (5 << 64) + 0x2345678)) % N
assert any(h[5] == hex(kc) for h in search(Sc, ec.mul(kc), 'cpu', 8, 128)), 'cpu control failed'
kg = (Sc + (777 << 80) + (0x80 << 112) + 123456) % N
assert any(h[5] == hex(kg) for h in search(Sc, ec.mul(kg), 'gpu', 800, 2)), 'gpu control failed'
print('planted CPU/GPU controls OK')
sh = lambda s: hashlib.sha256(s.encode()).hexdigest()
SEEDS = ['theseedisplanted', 'gsmg.io/theseedisplanted', sh('theseedisplanted'), sh('gsmg.io/theseedisplanted')]
gpu = len(sys.argv) > 1 and sys.argv[1] == 'gpu'
for sd in SEEDS:
    for lab, S in (('VanitySearch', vs_start(sd)), ('sha256-base', bw_start(sd))):
        h = search(S, ec.TGT, 'cpu', 64, 2048)          # CPU: 64 threads, j < 2^30
        print(f'CPU {lab:12s} seed={sd[:30]!r}: hits={h}', flush=True)
        if gpu and lab == 'VanitySearch':
            h = search(S, ec.TGT, 'gpu', 1 << 17, 4, gpus=(0, 1))   # GPU: 131072 threads x 2 GPUs, j < 2^21
            print(f'GPU {lab:12s} seed={sd[:30]!r}: hits={h}', flush=True)
